"""
Task 011 — Topological sort with cycle detection.

Implementation notes:
- Uses Kahn's algorithm (BFS-based) for topological sort with lexicographic tie-breaking.
- Cycle detection: if not all nodes are processed after Kahn's algorithm, a cycle exists.
- For cycle reporting, we use DFS to find an actual cycle among the unprocessed nodes.
- Dangling successors are checked before processing.
"""

import heapq
from collections import defaultdict


def topological_sort(graph: dict[str, list[str]]) -> list[str]:
    """
    Return a topological ordering of the nodes in `graph`.

    Raises ValueError if:
    - The graph contains a cycle (including self-loops).
    - A successor node is not a key in the graph (dangling successor).
    - Empty graph returns [].
    """
    if not graph:
        return []

    # Check for dangling successors
    for node, successors in graph.items():
        for succ in successors:
            if succ not in graph:
                raise ValueError(
                    f"node '{succ}' is referenced as a successor but is not a key in the graph"
                )

    # Compute in-degrees
    in_degree = {node: 0 for node in graph}
    for node, successors in graph.items():
        for succ in successors:
            in_degree[succ] += 1

    # Kahn's algorithm with a min-heap for lexicographic ordering
    # Initialize heap with all nodes that have in-degree 0
    heap = [node for node, deg in in_degree.items() if deg == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for succ in sorted(graph[node]):  # sorted for determinism (heap handles ordering)
            in_degree[succ] -= 1
            if in_degree[succ] == 0:
                heapq.heappush(heap, succ)

    if len(result) != len(graph):
        # There is a cycle — find it among nodes not yet processed
        remaining = {node for node in graph if node not in set(result)}
        cycle_nodes = _find_cycle(graph, remaining)
        raise ValueError(f"cycle detected involving: {', '.join(sorted(cycle_nodes))}")

    return result


def _find_cycle(graph: dict[str, list[str]], remaining: set) -> list[str]:
    """
    Find nodes involved in a cycle within the subgraph induced by `remaining`.
    Returns a list of node identifiers that form a cycle.
    """
    # DFS-based cycle detection on the subgraph of remaining nodes
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in remaining}
    cycle_nodes = []

    def dfs(node, path):
        nonlocal cycle_nodes
        color[node] = GRAY
        path.append(node)
        for succ in graph[node]:
            if succ not in remaining:
                continue
            if color[succ] == GRAY:
                # Found a cycle — extract it from path
                idx = path.index(succ)
                cycle_nodes = path[idx:]
                return True
            if color[succ] == WHITE:
                if dfs(succ, path):
                    return True
        path.pop()
        color[node] = BLACK
        return False

    for node in sorted(remaining):
        if color[node] == WHITE:
            if dfs(node, []):
                break

    return cycle_nodes if cycle_nodes else list(remaining)
